def compute_hypotenuse(x, y):
    """Calculate hypotenuse from legs x and y."""
    return (x**2 + y**2) ** 0.5


def pair_distances(points):
    """Return euclidean distances for point pairs."""
    return [compute_hypotenuse(x1 - x2, y1 - y2)
            for (x1, y1), (x2, y2) in points]

